-- legislators_seed.sql
-- Pre-aggregated VA legislator data: vote summaries, recent votes,
-- sponsored/co-sponsored bills.
-- Sources: openstates_va.db (votes, bills), polls.db (legiscan tables)
-- DO NOT EDIT BY HAND -- regenerate with generate_legislators_seed.py

-- ── va_legislator_vote_summary ──────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS va_legislator_vote_summary (
    voter_name   TEXT,
    session      TEXT,
    chamber      TEXT,
    party        TEXT,
    yes_count    INTEGER DEFAULT 0,
    no_count     INTEGER DEFAULT 0,
    not_voting   INTEGER DEFAULT 0,
    abstain      INTEGER DEFAULT 0,
    total_votes  INTEGER DEFAULT 0,
    PRIMARY KEY (voter_name, session)
);
DELETE FROM va_legislator_vote_summary WHERE session = '2026';


-- ── va_legislator_recent_votes ──────────────────────────────────────────────
DROP TABLE IF EXISTS va_legislator_recent_votes;
CREATE TABLE va_legislator_recent_votes (
    voter_name    TEXT,
    session       TEXT,
    bill_id       TEXT,
    vote_date     TEXT,
    option        TEXT,
    chamber       TEXT,
    motion        TEXT,
    title         TEXT,
    is_procedural INTEGER DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_lrv_voter_session ON va_legislator_recent_votes(voter_name, session);
CREATE INDEX IF NOT EXISTS idx_lrv_bill_session  ON va_legislator_recent_votes(bill_id, session);


-- ── va_legislator_sponsored_bills ───────────────────────────────────────────
CREATE TABLE IF NOT EXISTS va_legislator_sponsored_bills (
    legislator_name TEXT,
    session         TEXT,
    bill_id         TEXT,
    bill_number     TEXT,
    title           TEXT,
    status_label    TEXT,
    subject         TEXT,
    status_date     TEXT
);
DELETE FROM va_legislator_sponsored_bills WHERE session = '2026';


-- ── va_legislator_cosponsor_bills ───────────────────────────────────────────
CREATE TABLE IF NOT EXISTS va_legislator_cosponsor_bills (
    legislator_name TEXT,
    session         TEXT,
    bill_id         TEXT,
    bill_number     TEXT,
    title           TEXT,
    status_label    TEXT,
    subject         TEXT,
    sponsor_order   INTEGER
);
DELETE FROM va_legislator_cosponsor_bills WHERE session = '2026';

